<?php require_admin();$id=(int)($_GET['id']??0);$p=$id?q('SELECT * FROM productos WHERE id=?',[$id])->fetch():null;?><div class="container py-5"><a href="index.php?page=admin" class="text-decoration-none text-dark">← Volver al inventario</a><h1 class="my-4" style="font-size:3rem"><?= $p?'Editar producto #'.(int)$p['id']:'Nuevo producto' ?></h1><div class="surface p-4 p-md-5"><form method="post" action="actions.php" enctype="multipart/form-data" class="row g-3"><input type="hidden" name="action" value="admin_product"><?=csrf_input()?><input type="hidden" name="producto_id" value="<?=$id?>"><div class="col-md-8"><label class="form-label">Nombre</label><input class="form-control" name="nombre" required maxlength="170" value="<?=h($p['nombre']??'')?>"></div><div class="col-md-4"><label class="form-label">Categoría</label><select class="form-select" name="categoria"><?php foreach(['base'=>'Base proteica','sabor'=>'Sabor','suplemento'=>'Suplemento','fibra'=>'Fibra','pack'=>'Presentación'] as $k=>$v):?><option value="<?=h($k)?>" <?=($p['categoria']??'pack')===$k?'selected':''?>><?=h($v)?></option><?php endforeach ?></select></div><div class="col-12"><label class="form-label">Descripción</label><textarea class="form-control" name="descripcion" rows="4" required maxlength="1500"><?=h($p['descripcion']??'')?></textarea></div><div class="col-md-4"><label class="form-label">Precio (MXN)</label><input type="number" class="form-control" name="precio" step="0.01" min="0" required value="<?=h((string)($p['precio']??'0'))?>"></div><div class="col-md-4"><label class="form-label">Cantidad en almacén</label><input type="number" class="form-control" name="cantidad_almacen" min="0" required value="<?=h((string)($p['cantidad_almacen']??'0'))?>"></div><div class="col-md-4"><label class="form-label">Fotografía (JPG, PNG o WebP, hasta 2 MB)</label><input type="file" class="form-control" name="foto" accept="image/jpeg,image/png,image/webp"></div><div class="col-md-6"><label class="form-label">Fabricante</label><input class="form-control" name="fabricante" required value="<?=h($p['fabricante']??'crafted (demo)')?>"></div><div class="col-md-6"><label class="form-label">Origen</label><input class="form-control" name="origen" required value="<?=h($p['origen']??'México')?>"></div><?php if($p):?><div class="col-12"><img src="<?=h(product_image($p))?>" class="mini-product" alt="Foto actual"></div><?php endif ?><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="activo" id="active" <?=($p['activo']??1)?'checked':''?>><label class="form-check-label" for="active">Visible en catálogo</label></div></div><div class="col-12"><button class="btn btn-brand">Guardar producto</button></div></form></div></div>
